Не знаю, делал кто-то или нет, но решил, что быстрее сделать самому, чем искать по форуму. Мод добавляет поле для загрузки изображений в конструкторе шаблонов. После AJAX загрузки мод заменит значение предыдущего поля конструктора на прямой URL к картинке на fastpic.ru.<br />
Это мой первый мод и вообще первый опыт знакомства с движком, так что не судите строго. Надеюсь кому-то станет полезным. По желанию могу написать загрузку на другие сервисы.<br />
Для установки<br />
<ol>
<li data-xf-list-type="ol">Замените в <b>ajax.php</b>:<br />
<pre class="xfBb-code" data-lang="php">$ajax = new TorrentPier\Legacy\Ajax();</pre>на<br />
<pre class="xfBb-code" data-lang="php">class Ajax extends TorrentPier\Legacy\Ajax {
    function __construct() {
        parent::__construct();
        $this-&gt;valid_actions[&#039;ajax_load_pic&#039;] = [&#039;user&#039;];
    }
    function init() {
        parent::init();
        if (!$this-&gt;action) $this-&gt;action = $_GET[&#039;action&#039;];
    }
    function ajax_load_pic() {
        $data = array(
            &#039;file[]&#039; =&gt; new CurlFile($_FILES[&#039;img&#039;][&#039;tmp_name&#039;]),
            &#039;uploading&#039; =&gt; &#039;1&#039;
        );
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_HEADER, 1);
        curl_setopt($ch, CURLOPT_NOBODY, 1);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
        curl_setopt($ch, CURLOPT_URL, &#039;https://fastpic.ru/uploadmulti&#039;);
        curl_setopt($ch, CURLOPT_POST, 1);
        curl_setopt($ch, CURLOPT_POSTFIELDS, $data);
        $result = curl_exec($ch);
        preg_match(&#039;/http.*html/&#039;, $result, $matches);
        curl_setopt($ch, CURLOPT_URL, $matches[0]);
        curl_setopt($ch, CURLOPT_HEADER, 0);
        curl_setopt($ch, CURLOPT_NOBODY, 0);
        $result = curl_exec($ch);
        preg_match(&#039;/(https?.*?fastpic.ru\/big.*?)&quot;/&#039;, $result, $matches);
        $this-&gt;response[&#039;url&#039;] = $matches[1];
        curl_close($ch);
    }
}

$ajax = new Ajax();</pre></li>
