                dataType: &#039;json&#039;,
                contentType: false,
                data: fd,
                processData: false,
                success: data =&gt; {
                    if ($el.parent().prev().is(&#039;input&#039;)) $el.parent().prev().val(data.url);
                    $el.val(&#039;&#039;);
                }
