К сожалению не знаю как можно отредактировать свой первый пост и название темы, поэтому выкладываю следующим обновлённую версию.<br />
Из изменений:<br />
<ul>
<li data-xf-list-type="ul">добавлен сервис imageban.ru</li>
<li data-xf-list-type="ul">добавлен сервис *******.host</li>
<li data-xf-list-type="ul">добавлен селектор выбора сервиса в конструкторе</li>
<li data-xf-list-type="ul">добавлено поле выбора размера изображения в конструкторе</li>
<li data-xf-list-type="ul">оптимизация кода</li>
</ul><b>ajax.php:</b><br />
<pre class="xfBb-code" data-lang="php">class Ajax extends TorrentPier\Legacy\Ajax {
    function __construct() {
        parent::__construct();
        $this-&gt;valid_actions[&#039;ajax_load_pic&#039;] = [&#039;user&#039;];
    }
    function ajax_load_pic() {
        $ch = curl_init();
        $tmp = sys_get_temp_dir() . DIRECTORY_SEPARATOR . $_FILES[&#039;img&#039;][&#039;name&#039;];
        move_uploaded_file($_FILES[&#039;img&#039;][&#039;tmp_name&#039;], $tmp);
        $file = new CurlFile($tmp);
        $size = $this-&gt;request[&#039;size&#039;];
        switch ($this-&gt;request[&#039;service&#039;]) {
            case &#039;*******&#039;:
                $data = array(
                    &#039;File&#039; =&gt; $file,
                    &#039;OriginalFileName&#039; =&gt; &#039;blank.jpg&#039;,
                    &#039;MaxSize&#039; =&gt; $size,
                    &#039;PrevMaxSize&#039; =&gt; 360,
                    &#039;IsPublic&#039; =&gt; &#039;false&#039;,
                    &#039;NeedResize&#039; =&gt; $size?&#039;true&#039;:&#039;false&#039;
                );
                curl_setopt($ch, CURLOPT_URL, &#039;https://*******.host/Img/SaveImg2&#039;);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
                curl_setopt($ch, CURLOPT_POST, 1);
                curl_setopt($ch, CURLOPT_POSTFIELDS, $data);
                $result = json_decode(curl_exec($ch));
                $this-&gt;response[&#039;url&#039;] = $result-&gt;Url;
                break;
            case &#039;imageban&#039;:
                $data = array(
                    &#039;Filedata&#039; =&gt; $file,
                    &#039;prew&#039; =&gt; $size?$size:160
                );
                curl_setopt($ch, CURLOPT_URL, &#039;https://imageban.ru/up&#039;);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
                curl_setopt($ch, CURLOPT_POST, 1);
                curl_setopt($ch, CURLOPT_POSTFIELDS, $data);
                $result = json_decode(curl_exec($ch));
                $this-&gt;response[&#039;url&#039;] = $size?$result-&gt;files[0]-&gt;thumbs:$result-&gt;files[0]-&gt;link;
                break;
            case &#039;fastpic&#039;:
            default:
                $data = array(
                    &#039;file[]&#039; =&gt; $file,
                    &#039;check_orig_resize&#039; =&gt; !!$size,
                    &#039;orig_resize&#039; =&gt; $size,
                    &#039;uploading&#039; =&gt; &#039;1&#039;
                );
                curl_setopt($ch, CURLOPT_URL, &#039;https://fastpic.ru/uploadmulti&#039;);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
                curl_setopt($ch, CURLOPT_HEADER, 1);
                curl_setopt($ch, CURLOPT_NOBODY, 1);
                curl_setopt($ch, CURLOPT_POST, 1);
                curl_setopt($ch, CURLOPT_POSTFIELDS, $data);
                $result = curl_exec($ch);
                preg_match(&#039;/http.*html/&#039;, $result, $matches);
                curl_setopt($ch, CURLOPT_URL, $matches[0]);
                curl_setopt($ch, CURLOPT_HEADER, 0);
                curl_setopt($ch, CURLOPT_NOBODY, 0);
                $result = curl_exec($ch);
                preg_match(&#039;/(https?.*?fastpic.ru\/big.*?)&quot;/&#039;, $result, $matches);
                $this-&gt;response[&#039;url&#039;] = $matches[1];
        }
        curl_close($ch);
        unlink($tmp);
    }
}

$ajax = new Ajax();</pre><br />
